    "Fenêtre": "Окно",
    "Garde une config 1 offensive (lasers) et une config 2 défensive (bouclier / vitesse).": "Держите атакующий конфиг 1 (лазеры) и защитный конфиг 2 (щит / скорость).",
    "Générateur de Vitesse G3N-1010": "Генератор скорости G3N-1010",
