    "Le P.E.T avec un gear Auto-Loot double ta vitesse de ramassage.": "P.E.T с механизмом Auto-Loot удваивает скорость сбора.",
    "Légendaire": "Легендарный",
    "Les fenêtres du jeu": "Окна игры",
    "Les modules sont liés à une famille de vaisseau. Tire des modules dans l'onglet MODULES : ceux de Phoenix apparaîtront ici.": "Модули привязаны к семейству кораблей. Разыгрывайте модули во вкладке МОДУЛИ: модули для Phoenix появятся здесь.",
    "Les quêtes rapportent beaucoup au début : garde toujours des quêtes actives.": "В начале задания приносят много: всегда держите задания активными.",
    "Missions / Terminal de quêtes": "Миссии / Терминал заданий",
    "Nécessite au moins 4 drones": "Требуется минимум 4 дрона",
