    "Production passive de ressources et ventes aux enchères.": "Пассивное производство ресурсов и аукционы.",
    "Quêtes & passe": "Задания и пропуск",
    "quêtes → farm de NPC → minerais → raffinage → meilleur équipement → maps supérieures → Galaxy Gates.": "задания → фарм NPC → руда → переработка → лучшее снаряжение → карты выше → Galaxy Gate.",
    "Quêtes actives, objectifs et récompenses ; nouvelles quêtes au terminal.": "Активные задания, цели и награды; новые задания в терминале.",
    "Raffine Prometium / Endurium / Terbium et charge tes lasers.": "Перерабатывайте Prometium / Endurium / Terbium и заряжайте лазеры.",
