    "Rareté": "Редкость",
    "Recettes de minerais, upgrades d'équipement, vente au comptoir.": "Рецепты руды, улучшения снаряжения, продажа на торговой станции.",
    "répare-toi à la base, au portail le plus proche ou sur place selon les choix proposés.": "ремонт на базе, у ближайшего портала или на месте в зависимости от предложенных вариантов.",
    "Rien à raffiner pour le moment.": "Сейчас нечего перерабатывать.",
    "Roulette, modules équipés et comparateur.": "Рулетка, установленные модули и сравнение.",
    "Si tu perds plus de coque que tu n'en infliges, redescends d'une map.": "Если вы теряете больше корпуса, чем наносите, спуститесь на карту ниже.",
    "Skylab / Enchères": "Skylab / Аукцион",
    "Spins, construction des gates, multiplicateurs, historique.": "Вращения, постройка врат, множители, история.",
