    "Tout ce que tu possèdes, avec recherche et catégories.": "Всё, что у вас есть, с поиском и категориями.",
    "Toutes les fenêtres se déplacent par leur barre de titre, se réduisent avec": "Все окна перемещаются за заголовок, сворачиваются с помощью",
    "unités de minerais. Vends ou raffine quand elle est pleine.": "единиц руды. Продайте или переработайте, когда трюм полон.",
    "Utilise la munition": "Используйте боеприпасы",
