    "« Remettre à zéro » relance les compteurs.": "«Сброс» обнуляет счётчики.",
    "(bonus et apparence évoluent).": "(бонус и внешний вид развиваются).",
    "(NPC et box). Seuls le palladium et les Sun Box gardent leur gain complet.": "(NPC и ящики). Только палладий и Sun Box сохраняют полную выгоду.",
