    "Câble haute fréquence": "Высокочастотный кабель",
    "Charge un minerai sur les générateurs de bouclier. 1 minerai = 10 minutes. Duranium +10 %, Promerium +20 %, Seprom +40 %, Osmium +50 %.": "Заряжает руду в генераторы щита. 1 руда = 10 минут. Duranium +10 %, Promerium +20 %, Seprom +40 %, Osmium +50 %.",
    "Charge un minerai sur les générateurs de vitesse. 1 minerai = 10 minutes. Duranium +10 %, Promerium +20 %.": "Заряжает руду в генераторы скорости. 1 руда = 10 минут. Duranium +10 %, Promerium +20 %.",
    "Charge un minerai sur les lasers : +dégâts à chaque tir. 1 minerai = 10 tirs. Prometid +15 %, Promerium +30 %, Seprom +60 %, Osmium +50 %.": "Заряжает руду в лазеры: +урон каждого выстрела. 1 руда = 10 выстрелов. Prometid +15 %, Promerium +30 %, Seprom +60 %, Osmium +50 %.",
    "Charge un minerai sur les roquettes : +dégâts par roquette. 1 minerai = 10 tirs. Prometid +15 %, Promerium +30 %, Seprom +60 %, Osmium +50 %.": "Заряжает руду в ракеты: +урон каждой ракеты. 1 руда = 10 выстрелов. Prometid +15 %, Promerium +30 %, Seprom +60 %, Osmium +50 %.",
