    "Priorité : plus haute = tuée d'abord (10 avant 1). Négative = immédiat : dès qu'il est en vue, il passe devant tout (-10 avant -1 ; à égalité, le plus proche).": "Приоритет: выше = убивается раньше (10 раньше 1). Отрицательный = немедленно: как только в поле зрения, идёт прежде всего (-10 раньше -1; при равенстве — ближайший).",
