    "= VRU. Les maps vont de X-1 (débutant) à X-8 (très dur), plus les BL.": "= VRU. Карты идут от X-1 (новичок) до X-8 (очень сложно), плюс BL.",
    "▶ démarre, ⏸ met en pause ; la touche Start / Stop Bot fait pareil.": "▶ запускает, ⏸ ставит на паузу; клавиша Старт / Стоп бота делает то же.",
