    "70 500 000–81 500 000 crédits, 8 500 000–12 500 000 XP, 52 500–72 500 honneur, 1 500–2 500 Rinusk, 120–140 Traceurs Blacklight, 30–45 Cerebrum Mindfire, 250–350 Fragments éternels": "70 500 000–81 500 000 кредитов, 8 500 000–12 500 000 XP, 52 500–72 500 чести, 1 500–2 500 Rinusk, 120–140 трассеров Blacklight, 30–45 Mindfire Cerebrum, 250–350 фрагментов Eternal",
