    "Admiré": "Почитаемый",
    "Alpha, Beta et Gamma partagent une seule roue (Ensemble ABG) ; les autres ont leur roue.": "Alpha, Beta и Gamma делят одно колесо (набор ABG); у остальных своё колесо.",
    "Apis et Zeus :": "Apis и Zeus:",
    "Après destruction : réparation à la base, au portail le plus proche ou sur place quand c'est disponible.": "После уничтожения: ремонт на базе, у ближайшего портала или на месте, если доступно.",
