    "Attaquer ou rester en combat suspend la protection.": "Атака или пребывание в бою приостанавливает защиту.",
    "Attends le message de fin avant le retour en X-1.": "Дождитесь финального сообщения, прежде чем вернуться на X-1.",
    "Au max": "Максимум",
    "Au moins un NPC coché (mode Kill) ?": "Отмечен хотя бы один NPC (режим Kill)?",
    "Augmente la capacité de stockage de toutes les ressources.": "Увеличивает вместимость хранилища всех ресурсов.",
    "Augmente ton bouclier max.": "Увеличивает ваш макс. щит.",
    "Autour des bases, de certains portails et modules : les NPC ne t'engagent pas.": "Вокруг баз, некоторых порталов и модулей: NPC вас не атакуют.",
    "avant que la coque se répare et que le bouclier se recharge normalement. Chaque coup relance le délai.": "до того, как корпус начнёт ремонтироваться, а щит — нормально заряжаться. Каждое попадание сбрасывает задержку.",
    "Barre rapide (slots 1 à 20) :": "Панель быстрого доступа (ячейки 1–20):",
    "Barre rapide et munitions": "Панель быстрого доступа и боеприпасы",
    "Barrière, X ou Chauve-Souris (dégâts et XP contre NPC).": "Барьер, X или Летучая мышь (урон и XP против NPC).",
    "Base de vente : automatique, X-1, X-8 ou pirate 5-2.": "База продажи: автоматически, X-1, X-8 или пиратская 5-2.",
