    "boutons + / − pour zoomer.": "кнопки + / − для масштаба.",
    "Brise-blindé": "Пробиватель брони",
    "Capacité :": "Вместимость:",
    "Caractéristiques": "Характеристики",
    "Carburant : sans carburant le P.E.T reste au hangar. Achat rapide +1 000 dans la fenêtre P.E.T.": "Топливо: без топлива P.E.T остаётся в ангаре. Быстрая покупка +1 000 в окне P.E.T.",
    "casse les verrouillages des joueurs et NPC qui te visent, retire gel et ralentissement, empêche leur retour pendant 3 s.": "сбрасывает захват игроков и NPC, нацеленных на вас, снимает заморозку и замедление, не даёт им вернуться 3 с.",
    "Ce tableau lit tes vraies touches : modifie-les dans Paramètres → Commandes (clique une ligne puis appuie la nouvelle touche).": "Эта таблица читает ваши текущие клавиши: измените их в Настройки → Управление (нажмите на строку, затем новую клавишу).",
    "Certaines munitions, roquettes et formations s'obtiennent uniquement ici.": "Некоторые боеприпасы, ракеты и формации можно получить только здесь.",
    "Certaines quêtes, kills et exploits débloquent des titres.": "Некоторые задания, убийства и подвиги открывают титулы.",
    "Ces ressources ne prennent pas de place en soute.": "Эти ресурсы не занимают место в трюме.",
    "Chance de réussite des roquettes.": "Шанс успеха ракет.",
    "Change l'apparence du vaisseau ciblé (visuel uniquement)": "Меняет вид корабля-цели (только визуально)",
    "Changer de firme annule toutes les quêtes en cours.": "Смена компании отменяет все текущие задания.",
    "Changer de firme coûte": "Смена компании стоит",
    "Chaque carte de membre montre vaisseau, map, distance, coque, bouclier et sa cible.": "Карточка каждого участника показывает корабль, карту, расстояние, корпус, щит и его цель.",
    "Chaque chargement coûte 100 unités du minerai choisi. Changer de minerai remplace le stock en cours. Le chargement se fait dans la fenêtre Raffinage (onglet Upgrade) ou automatiquement (Soute du BOT).": "Каждая зарядка стоит 100 единиц выбранной руды. Смена руды заменяет текущий запас. Зарядка выполняется в окне переработки (вкладка Upgrade) или автоматически (трюм бота).",
    "Chaque compétence a des prérequis (points investis dans d'autres compétences).": "У каждого навыка есть требования (очки, вложенные в другие навыки).",
    "chaque famille existe en 3 forces ; Boss ≈ ×4 et Uber ≈ ×8 les gains du normal.": "каждое семейство бывает 3 видов силы; Boss ≈ ×4 и Uber ≈ ×8 от обычной выгоды.",
    "Chaque firme a une base en X-1 et en X-8 : réparation, comptoir, zone sûre.": "У каждой компании есть база в X-1 и X-8: ремонт, торговая станция, безопасная зона.",
    "Chaque hangar a 2 configurations indépendantes : bascule avec la touche Changer configuration.": "У каждого ангара 2 независимые конфигурации: переключайте клавишей «Сменить конфигурацию».",
    "Chaque module a une couleur (rareté), un type et 1 à plusieurs statistiques.": "У каждого модуля есть цвет (редкость), тип и 1 или более параметров.",
    "Chaque NPC laisse une cargo-box (minerais) réservée au tueur.": "Каждый NPC оставляет грузовой ящик (руда), предназначенный убийце.",
    "Chaque objectif terminé débloque ses récompenses dans la fenêtre Passe de combat.": "Каждая выполненная цель открывает награды в окне боевого пропуска.",
    "Chaque spin peut donner des pièces ; à 100 % des pièces, la gate est construite.": "Каждое вращение может дать детали; при 100 % деталей врата построены.",
    "Chaque vaisseau acheté crée un hangar ; active-le dans la fenêtre Hangars.": "Каждый купленный корабль создаёт ангар; активируйте его в окне ангаров.",
    "Charge Duranium / Promerium sur le bouclier.": "Заряжайте Duranium / Promerium в щит.",
    "Charger son équipement (Upgrade)": "Зарядка снаряжения (Upgrade)",
    "Choisis le titre affiché sous ton pseudo dans la fenêtre Titres.": "Выберите титул, отображаемый под вашим именем, в окне титулов.",
    "Choisis les box à ramasser.": "Выберите, какие ящики собирать.",
    "Cible verrouillée ?": "Цель захвачена?",
    "Classement → NPC & Grades : ton grade actuel, le suivant et tes kills par NPC.": "Рейтинг → NPC и ранги: ваш текущий ранг, следующий и ваши убийства по каждому NPC.",
