    "Clique une box pour voler dessus : elle est ramassée au contact.": "Нажмите на ящик, чтобы полететь к нему: он подбирается при контакте.",
    "Clique une cible pour la verrouiller, puis active le tir laser.": "Нажмите на цель, чтобы захватить её, затем включите огонь лазеров.",
    "Clique une munition (ou sa touche) pour la sélectionner : le tir laser l'utilise aussitôt.": "Нажмите на боеприпас (или его клавишу), чтобы выбрать его: лазерный огонь сразу его использует.",
